// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public { c = new PrivateBank(address(this)); }

    function testFuzz_property(uint256 amount, address sender) public {
        uint256 minDep = c.MinDeposit();
        vm.assume(amount >= minDep && amount <= type(uint256).max / 2);

        vm.assume(sender != address(0));

        uint256 balanceBefore = c.balances(sender);
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("Deposit()")
        );

        uint256 balanceAfter = c.balances(sender);

        assertTrue(!ok || balanceAfter == balanceBefore + amount);
    }
}
